namespace MyApp.Evaluation;

/// <summary>
/// Represents a single evaluation scenario for the agentic app.
/// </summary>
public sealed class EvaluationScenario
{
    /// <summary>
    /// A short identifier for this scenario.
    /// </summary>
    public required string Name { get; init; }

    /// <summary>
    /// The input prompt or message sequence to send to the agent.
    /// </summary>
    public required string[] Turns { get; init; }

    /// <summary>
    /// Assertions to evaluate against the agent's responses.
    /// </summary>
    public required EvaluationAssertion[] Assertions { get; init; }

    /// <summary>
    /// Optional tags for filtering scenarios.
    /// </summary>
    public string[] Tags { get; init; } = [];
}

/// <summary>
/// A single assertion to evaluate against an agent response.
/// </summary>
public sealed class EvaluationAssertion
{
    /// <summary>
    /// The type of assertion (e.g., "contains", "not_contains", "regex", "tool_called").
    /// </summary>
    public required string Type { get; init; }

    /// <summary>
    /// The expected value or pattern for the assertion.
    /// </summary>
    public required string Value { get; init; }

    /// <summary>
    /// Which turn (0-based) this assertion applies to. Defaults to the last turn.
    /// </summary>
    public int? Turn { get; init; }
}

namespace MyApp.Evaluation;

/// <summary>
/// The result of running a single evaluation scenario.
/// </summary>
public sealed class EvaluationResult
{
    public required string ScenarioName { get; init; }
    public required bool Passed { get; init; }
    public required TimeSpan Duration { get; init; }
    public required AssertionResult[] AssertionResults { get; init; }
    public string[] AgentResponses { get; init; } = [];
    public string? Error { get; init; }
}

/// <summary>
/// The result of evaluating a single assertion.
/// </summary>
public sealed class AssertionResult
{
    public required string Type { get; init; }
    public required string Value { get; init; }
    public required bool Passed { get; init; }
    public string? Reason { get; init; }
}

using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads evaluation scenarios from YAML files in the Scenarios directory.
/// Uses a minimal parser to avoid extra dependencies.
/// </summary>
public static partial class ScenarioLoader
{
    public static IEnumerable<EvaluationScenario> LoadFromDirectory(string path)
    {
        var dir = Path.Combine(AppContext.BaseDirectory, path);
        if (!Directory.Exists(dir))
        {
            yield break;
        }

        foreach (var file in Directory.GetFiles(dir, "*.yaml"))
        {
            foreach (var scenario in ParseYamlFile(file))
            {
                yield return scenario;
            }
        }
    }

    private static IEnumerable<EvaluationScenario> ParseYamlFile(string filePath)
    {
        var lines = File.ReadAllLines(filePath);
        var scenarios = new List<EvaluationScenario>();

        string? name = null;
        var turns = new List<string>();
        var assertions = new List<EvaluationAssertion>();
        var tags = new List<string>();
        string? section = null;

        foreach (var rawLine in lines)
        {
            var line = rawLine;

            if (string.IsNullOrWhiteSpace(line) || line.TrimStart().StartsWith('#'))
            {
                continue;
            }

            if (NameRegex().Match(line) is { Success: true } nameMatch)
            {
                if (name is not null)
                {
                    scenarios.Add(BuildScenario(name, turns, assertions, tags));
                    turns = [];
                    assertions = [];
                    tags = [];
                }
                name = nameMatch.Groups[1].Value.Trim();
                section = null;
                continue;
            }

            if (SectionRegex().Match(line) is { Success: true } sectionMatch)
            {
                section = sectionMatch.Groups[1].Value.Trim();
                continue;
            }

            if (section == "turns" && ListItemRegex().Match(line) is { Success: true } turnMatch)
            {
                turns.Add(turnMatch.Groups[1].Value.Trim());
                continue;
            }

            if (section == "tags" && ListItemRegex().Match(line) is { Success: true } tagMatch)
            {
                tags.Add(tagMatch.Groups[1].Value.Trim());
                continue;
            }

            if (section == "assertions" && AssertionRegex().Match(line) is { Success: true } assertMatch)
            {
                assertions.Add(new EvaluationAssertion
                {
                    Type = assertMatch.Groups[1].Value.Trim(),
                    Value = assertMatch.Groups[2].Value.Trim()
                });
            }
        }

        if (name is not null)
        {
            scenarios.Add(BuildScenario(name, turns, assertions, tags));
        }

        return scenarios;
    }

    private static EvaluationScenario BuildScenario(
        string name,
        List<string> turns,
        List<EvaluationAssertion> assertions,
        List<string> tags) => new()
    {
        Name = name,
        Turns = turns.ToArray(),
        Assertions = assertions.ToArray(),
        Tags = tags.ToArray()
    };

    [GeneratedRegex(@"^- name:\s*(.+)$")]
    private static partial Regex NameRegex();

    [GeneratedRegex(@"^\s+(turns|assertions|tags):\s*$")]
    private static partial Regex SectionRegex();

    [GeneratedRegex(@"^\s+- (.+)$")]
    private static partial Regex ListItemRegex();

    [GeneratedRegex(@"^\s+- type:\s*(\w+)\s+value:\s*(.+)$")]
    private static partial Regex AssertionRegex();
}

using System.Diagnostics;
using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Runs evaluation scenarios against the agentic app and produces results.
/// </summary>
public sealed class EvaluationHarness
{
    private readonly Func<string[], Task<string[]>> _agentInvoker;

    /// <summary>
    /// Creates an evaluation harness with the given agent invoker function.
    /// The invoker accepts an array of turns (prompts) and returns an array of responses.
    /// </summary>
    public EvaluationHarness(Func<string[], Task<string[]>> agentInvoker)
    {
        _agentInvoker = agentInvoker;
    }

    /// <summary>
    /// Runs a single evaluation scenario and returns the result.
    /// </summary>
    public async Task<EvaluationResult> RunAsync(EvaluationScenario scenario)
    {
        var sw = Stopwatch.StartNew();
        string[] responses;

        try
        {
            responses = await _agentInvoker(scenario.Turns);
        }
        catch (Exception ex)
        {
            sw.Stop();
            return new EvaluationResult
            {
                ScenarioName = scenario.Name,
                Passed = false,
                Duration = sw.Elapsed,
                AssertionResults = [],
                Error = ex.Message
            };
        }

        sw.Stop();

        var assertionResults = scenario.Assertions
            .Select(a => Evaluate(a, responses))
            .ToArray();

        return new EvaluationResult
        {
            ScenarioName = scenario.Name,
            Passed = assertionResults.All(r => r.Passed),
            Duration = sw.Elapsed,
            AssertionResults = assertionResults,
            AgentResponses = responses
        };
    }

    /// <summary>
    /// Runs all provided scenarios and returns results.
    /// </summary>
    public async Task<EvaluationResult[]> RunAllAsync(IEnumerable<EvaluationScenario> scenarios)
    {
        var results = new List<EvaluationResult>();
        foreach (var scenario in scenarios)
        {
            results.Add(await RunAsync(scenario));
        }
        return results.ToArray();
    }

    private static AssertionResult Evaluate(EvaluationAssertion assertion, string[] responses)
    {
        if (responses.Length == 0)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = "No responses received from agent"
            };
        }

        var turnIndex = assertion.Turn ?? (responses.Length - 1);
        if (turnIndex >= responses.Length)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Turn {turnIndex} not found (only {responses.Length} responses)"
            };
        }

        var response = responses[turnIndex];

        return assertion.Type.ToLowerInvariant() switch
        {
            "contains" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase),
                Reason = response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase)
                    ? null
                    : $"Response does not contain '{assertion.Value}'"
            },
            "not_contains" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = !response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase),
                Reason = !response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase)
                    ? null
                    : $"Response unexpectedly contains '{assertion.Value}'"
            },
            "regex" => EvaluateRegex(assertion, response),
            "not_empty" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = !string.IsNullOrWhiteSpace(response),
                Reason = string.IsNullOrWhiteSpace(response) ? "Response is empty" : null
            },
            _ => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Unknown assertion type: {assertion.Type}"
            }
        };
    }

    private static AssertionResult EvaluateRegex(EvaluationAssertion assertion, string response)
    {
        try
        {
            var match = Regex.IsMatch(response, assertion.Value, RegexOptions.IgnoreCase);
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = match,
                Reason = match ? null : $"Response does not match pattern '{assertion.Value}'"
            };
        }
        catch (RegexParseException ex)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Invalid regex pattern: {ex.Message}"
            };
        }
    }
}

namespace MyApp.Evaluation;

/// <summary>
/// xUnit integration that loads scenarios and runs them through the evaluation harness.
/// Subclass this and provide your agent invoker to run evaluations as tests.
/// </summary>
public abstract class EvaluationTests
{
    private readonly EvaluationHarness _harness;

    protected EvaluationTests(Func<string[], Task<string[]>> agentInvoker)
    {
        _harness = new EvaluationHarness(agentInvoker);
    }

    protected string ScenariosPath { get; init; } = "Scenarios";

    public static IEnumerable<object[]> GetScenarioData(string path = "Scenarios")
    {
        var scenarios = ScenarioLoader.LoadFromDirectory(path);
        foreach (var scenario in scenarios)
        {
            yield return [scenario];
        }
    }

    protected async Task RunScenarioAsync(EvaluationScenario scenario)
    {
        var result = await _harness.RunAsync(scenario);

        if (!result.Passed)
        {
            var failures = result.AssertionResults
                .Where(a => !a.Passed)
                .Select(a => $"  [{a.Type}] {a.Value}: {a.Reason}");

            var message = $"Scenario '{result.ScenarioName}' failed:\n{string.Join('\n', failures)}";
            if (result.Error is not null)
            {
                message += $"\nError: {result.Error}";
            }

            Assert.Fail(message);
        }
    }
}

namespace MyApp.Evaluation;

/// <summary>
/// Sample evaluation tests demonstrating the harness with an echo agent.
/// Replace the agent invoker with your actual agentic app client.
/// </summary>
public sealed class SampleEvaluationTests : EvaluationTests
{
    public SampleEvaluationTests()
        : base(EchoAgentInvoker)
    {
    }

    /// <summary>
    /// Placeholder agent invoker that echoes inputs back.
    /// Replace this with an HTTP client or SDK call to your agentic app.
    /// </summary>
    private static Task<string[]> EchoAgentInvoker(string[] turns)
    {
        var responses = turns.Select(t => $"Echo: {t}").ToArray();
        return Task.FromResult(responses);
    }

    [Theory]
    [MemberData(nameof(LoadScenarios))]
    public async Task EvaluateScenario(EvaluationScenario scenario)
    {
        await RunScenarioAsync(scenario);
    }

    public static IEnumerable<object[]> LoadScenarios() => GetScenarioData();
}

