using System.Diagnostics;
using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Runs evaluation scenarios against the agentic app and produces results.
/// </summary>
public sealed class EvaluationHarness
{
    private readonly Func<string[], Task<string[]>> _agentInvoker;

    /// <summary>
    /// Creates an evaluation harness with the given agent invoker function.
    /// The invoker accepts an array of turns (prompts) and returns an array of responses.
    /// </summary>
    public EvaluationHarness(Func<string[], Task<string[]>> agentInvoker)
    {
        _agentInvoker = agentInvoker;
    }

    /// <summary>
    /// Runs a single evaluation scenario and returns the result.
    /// </summary>
    public async Task<EvaluationResult> RunAsync(EvaluationScenario scenario)
    {
        var sw = Stopwatch.StartNew();
        string[] responses;

        try
        {
            responses = await _agentInvoker(scenario.Turns);
        }
        catch (Exception ex)
        {
            sw.Stop();
            return new EvaluationResult
            {
                ScenarioName = scenario.Name,
                Passed = false,
                Duration = sw.Elapsed,
                AssertionResults = [],
                Error = ex.Message
            };
        }

        sw.Stop();

        var assertionResults = scenario.Assertions
            .Select(a => Evaluate(a, responses))
            .ToArray();

        return new EvaluationResult
        {
            ScenarioName = scenario.Name,
            Passed = assertionResults.All(r => r.Passed),
            Duration = sw.Elapsed,
            AssertionResults = assertionResults,
            AgentResponses = responses
        };
    }

    /// <summary>
    /// Runs all provided scenarios and returns results.
    /// </summary>
    public async Task<EvaluationResult[]> RunAllAsync(IEnumerable<EvaluationScenario> scenarios)
    {
        var results = new List<EvaluationResult>();
        foreach (var scenario in scenarios)
        {
            results.Add(await RunAsync(scenario));
        }
        return results.ToArray();
    }

    private static AssertionResult Evaluate(EvaluationAssertion assertion, string[] responses)
    {
        if (responses.Length == 0)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = "No responses received from agent"
            };
        }

        var turnIndex = assertion.Turn ?? (responses.Length - 1);
        if (turnIndex >= responses.Length)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Turn {turnIndex} not found (only {responses.Length} responses)"
            };
        }

        var response = responses[turnIndex];

        return assertion.Type.ToLowerInvariant() switch
        {
            "contains" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase),
                Reason = response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase)
                    ? null
                    : $"Response does not contain '{assertion.Value}'"
            },
            "not_contains" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = !response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase),
                Reason = !response.Contains(assertion.Value, StringComparison.OrdinalIgnoreCase)
                    ? null
                    : $"Response unexpectedly contains '{assertion.Value}'"
            },
            "regex" => EvaluateRegex(assertion, response),
            "not_empty" => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = !string.IsNullOrWhiteSpace(response),
                Reason = string.IsNullOrWhiteSpace(response) ? "Response is empty" : null
            },
            _ => new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Unknown assertion type: {assertion.Type}"
            }
        };
    }

    private static AssertionResult EvaluateRegex(EvaluationAssertion assertion, string response)
    {
        try
        {
            var match = Regex.IsMatch(response, assertion.Value, RegexOptions.IgnoreCase);
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = match,
                Reason = match ? null : $"Response does not match pattern '{assertion.Value}'"
            };
        }
        catch (RegexParseException ex)
        {
            return new AssertionResult
            {
                Type = assertion.Type,
                Value = assertion.Value,
                Passed = false,
                Reason = $"Invalid regex pattern: {ex.Message}"
            };
        }
    }
}

