namespace MyApp.Evaluation;

/// <summary>
/// xUnit integration that loads scenarios and runs them through the evaluation harness.
/// Subclass this and provide your agent invoker to run evaluations as tests.
/// </summary>
public abstract class EvaluationTests
{
    private readonly EvaluationHarness _harness;

    protected EvaluationTests(Func<string[], Task<string[]>> agentInvoker)
    {
        _harness = new EvaluationHarness(agentInvoker);
    }

    protected string ScenariosPath { get; init; } = "Scenarios";

    public static IEnumerable<object[]> GetScenarioData(string path = "Scenarios")
    {
        var scenarios = ScenarioLoader.LoadFromDirectory(path);
        foreach (var scenario in scenarios)
        {
            yield return [scenario];
        }
    }

    protected async Task RunScenarioAsync(EvaluationScenario scenario)
    {
        var result = await _harness.RunAsync(scenario);

        if (!result.Passed)
        {
            var failures = result.AssertionResults
                .Where(a => !a.Passed)
                .Select(a => $"  [{a.Type}] {a.Value}: {a.Reason}");

            var message = $"Scenario '{result.ScenarioName}' failed:\n{string.Join('\n', failures)}";
            if (result.Error is not null)
            {
                message += $"\nError: {result.Error}";
            }

            Assert.Fail(message);
        }
    }
}

